// ServerInterface represents all server handlers.
type ServerInterface interface {
	// Expand a partial application configuration into its complete form.
	// (POST /api/v1/apps/expand)
	ExpandApps(w http.ResponseWriter, r *http.Request)
	// Read Borq-rendered Kubernetes manifests back into a complete application configuration.
	// (POST /api/v1/apps/inspect)
	InspectApps(w http.ResponseWriter, r *http.Request)
	// Render a complete application configuration into Helm values and Kubernetes manifests.
	// (POST /api/v1/apps/render)
	RenderApps(w http.ResponseWriter, r *http.Request)
	// Read management component installation state.
	// (GET /api/v1/management/components)
	GetManagementComponents(w http.ResponseWriter, r *http.Request)
	// Upgrade management components in their explicit dependency order.
	// (POST /api/v1/management/components/upgrade)
	UpgradeManagementComponents(w http.ResponseWriter, r *http.Request)
	// Poll asynchronous application and rollout status.
	// (GET /api/v1/operations/{operation})
	GetOperation(w http.ResponseWriter, r *http.Request, operation string)
	// List organizations.
	// (GET /api/v1/organizations)
	ListOrganizations(w http.ResponseWriter, r *http.Request)
	// Create or retrieve an organization.
	// (PUT /api/v1/organizations/{organization})
	PutOrganization(w http.ResponseWriter, r *http.Request, organization string)
	// List clusters registered in this organization.
	// (GET /api/v1/organizations/{organization}/clusters)
	ListClusters(w http.ResponseWriter, r *http.Request, organization string)
	// Save a cluster registration, create its initial space, and optionally queue target setup.
	// (PUT /api/v1/organizations/{organization}/clusters/{cluster})
	PutCluster(w http.ResponseWriter, r *http.Request, organization string, cluster string)
	// Read deployment target component installation state.
	// (GET /api/v1/organizations/{organization}/clusters/{cluster}/components)
	GetClusterComponents(w http.ResponseWriter, r *http.Request, organization string, cluster string)
	// Compare target components without installing or enqueueing anything.
	// (GET /api/v1/organizations/{organization}/clusters/{cluster}/components/diff)
	DiffClusterComponents(w http.ResponseWriter, r *http.Request, organization string, cluster string, params DiffClusterComponentsParams)
	// Queue reconciliation of missing or failed target components.
	// (POST /api/v1/organizations/{organization}/clusters/{cluster}/components/reconcile)
	ReconcileClusterComponents(w http.ResponseWriter, r *http.Request, organization string, cluster string)
	// Queue an explicit target component upgrade.
	// (POST /api/v1/organizations/{organization}/clusters/{cluster}/components/upgrade)
	UpgradeClusterComponents(w http.ResponseWriter, r *http.Request, organization string, cluster string)
	// Download the registered cluster's selected kubeconfig.
	// (GET /api/v1/organizations/{organization}/clusters/{cluster}/kubeconfig)
	GetClusterKubeconfig(w http.ResponseWriter, r *http.Request, organization string, cluster string)
	// List spaces in this organization.
	// (GET /api/v1/organizations/{organization}/spaces)
	ListSpaces(w http.ResponseWriter, r *http.Request, organization string)
	// Read space binding, accepted desired configuration, and revision state.
	// (GET /api/v1/organizations/{organization}/spaces/{space})
	GetSpace(w http.ResponseWriter, r *http.Request, organization string, space string)
	// Create a space bound to a registered cluster.
	// (PUT /api/v1/organizations/{organization}/spaces/{space})
	PutSpace(w http.ResponseWriter, r *http.Request, organization string, space string)
	// Read the space's expanded app configuration and exact saved manifests.
	// (GET /api/v1/organizations/{organization}/spaces/{space}/apps)
	ListApps(w http.ResponseWriter, r *http.Request, organization string, space string)
	// List the latest published version of each named environment group.
	// (GET /api/v1/organizations/{organization}/spaces/{space}/environment-groups)
	ListEnvironmentGroups(w http.ResponseWriter, r *http.Request, organization string, space string)
	// Read a config latest version including full values.
	// (GET /api/v1/organizations/{organization}/spaces/{space}/environment-groups/{group})
	GetEnvironmentGroup(w http.ResponseWriter, r *http.Request, organization string, space string, group string)
	// Create a new config family from an existing published version.
	// (POST /api/v1/organizations/{organization}/spaces/{space}/environment-groups/{group}/clone)
	CloneEnvironmentGroup(w http.ResponseWriter, r *http.Request, organization string, space string, group string)
	// Publish a complete immutable environment group version.
	// (POST /api/v1/organizations/{organization}/spaces/{space}/environment-groups/{group}/versions)
	PublishEnvironmentGroup(w http.ResponseWriter, r *http.Request, organization string, space string, group string)
	// Read an existing config version including full values.
	// (GET /api/v1/organizations/{organization}/spaces/{space}/environment-groups/{group}/versions/{version})
	GetEnvironmentGroupVersion(w http.ResponseWriter, r *http.Request, organization string, space string, group string, version string)
	// Merge and expand a partial update, observe live resources, and save an immutable plan.
	// (POST /api/v1/organizations/{organization}/spaces/{space}/plans)
	PostPlan(w http.ResponseWriter, r *http.Request, organization string, space string)
	// Retrieve a saved plan and its exact rendering artifacts.
	// (GET /api/v1/plans/{plan})
	GetPlan(w http.ResponseWriter, r *http.Request, plan string)
	// Accept and execute the exact saved plan for the whole space.
	// (POST /api/v1/plans/{plan}/apply)
	ApplyPlan(w http.ResponseWriter, r *http.Request, plan string)
}

